legacy_c3_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    helmet_patches = image_patch.find("helmet")
    person_patches = image_patch.find("person")

    if not helmet_patches or not person_patches:
        return image_patch

    yellow_helmet_persons = [
        p for p in person_patches 
        if any(hlmt for hlmt in helmet_patches if hlmt.overlaps_with(*p.bbox))
    ]

    if not yellow_helmet_persons:
        return image_patch

    return depth_order(yellow_helmet_persons)[0]

